-- UK demo studies for a LOCAL Supabase stack (generated by samples/uk-demo/generate.cjs).
-- Northbridge CRO runs RELAPSE-STOP for Meridian Neurosciences; Brightpath sponsors LUMINA-NB2 directly.
do $$
declare
  v_cro uuid; v_bright uuid; v_uk uuid; v_meridian uuid; v_brightpath uuid; v_trial uuid; v_site uuid;
begin
  select id into v_cro from public.tenants where name = 'Northbridge CRO';
  if v_cro is null then raise exception 'Run supabase/tests/local/seed.sh first (creates Northbridge CRO)'; end if;
  select id into v_uk from public.countries where code = 'GB' limit 1;
  insert into public.tenants (name, client_type) values ('Brightpath Children''s Cancer Research', 'sponsor_direct') returning id into v_bright;
  insert into public.sponsors (tenant_id, name, code, legal_name, billing_contact_name) values (v_cro, 'Meridian Neurosciences Ltd', 'MNS', 'Meridian Neurosciences Ltd', 'Dr Laura Pennington, Head of Clinical Operations') returning id into v_meridian;
  insert into public.sponsors (tenant_id, name, code, legal_name, billing_contact_name) values (v_bright, 'Brightpath Children''s Cancer Research', 'BPC', 'Brightpath Children''s Cancer Research', 'Dr Imogen Hartley, Director of Research') returning id into v_brightpath;
  insert into public.trials (tenant_id, sponsor_id, name, short_title, protocol_number, protocol_version, study_type, phase, therapeutic_area, indication, population, min_age_years, max_age_years, randomised, blinding, arms_count, comparator, target_enrollment, iras_id, chief_investigator, lifecycle_status, planned_start_date, recruitment_end_date, planned_end_date, requires_visit_verification)
  values (v_cro, v_meridian, 'RELAPSE-STOP: A Phase III, Randomised, Double-Blind, Double-Dummy Study of Ovalitinib (MNS-2207), an Oral BTK Inhibitor, versus Teriflunomide in Adults with Relapsing Multiple Sclerosis', 'RELAPSE-STOP', 'MNS-2207-301', '2.0', 'interventional', 'phase_3', 'Neurology', 'Relapsing multiple sclerosis', 'adult', 18, 55, true, 'double_blind', 2, 'Teriflunomide 14 mg once daily', 120, '1009871', 'Prof. Daniel Whitcombe', 'setup', '2026-06-01', '2027-06-30', '2029-03-31', true)
  returning id into v_trial;
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_cro, 'Aire Valley Neuroscience Centre', v_uk, 'Becket Lane', 'Leeds', 'LS9 7QA', 'Dr Hannah Okafor', 'hannah.okafor@airevalley.example', 'Sam Patel', 'sam.patel@airevalley.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_cro, 'Thames Bridge MS Clinical Research Unit', v_uk, 'Riverside Walk', 'London', 'SE1 9XR', 'Prof. Daniel Whitcombe', 'd.whitcombe@thamesbridge.example', 'Priya Raman', 'priya.raman@thamesbridge.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_cro, 'Irwell Royal Infirmary Neurology Research Unit', v_uk, 'Oxford Approach', 'Manchester', 'M13 9QP', 'Dr Aisha Mahmood', 'aisha.mahmood@irwell.example', 'Tom Gallagher', 'tom.gallagher@irwell.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_cro, 'Edgbaston Park Neurology Research Centre', v_uk, 'Mindelsohn Row', 'Birmingham', 'B15 2RX', 'Dr Richard Ellison', 'richard.ellison@edgbastonpark.example', 'Grace Mensah', 'grace.mensah@edgbastonpark.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_cro, 'Clyde Valley Institute of Neurological Sciences', v_uk, 'Govan Approach', 'Glasgow', 'G51 4XQ', 'Dr Fiona MacLeod', 'fiona.macleod@clydeview.example', 'Euan Fraser', 'euan.fraser@clydeview.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
  insert into public.trials (tenant_id, sponsor_id, name, short_title, protocol_number, protocol_version, study_type, phase, therapeutic_area, indication, population, min_age_years, max_age_years, randomised, blinding, arms_count, comparator, target_enrollment, iras_id, chief_investigator, lifecycle_status, planned_start_date, recruitment_end_date, planned_end_date, requires_visit_verification)
  values (v_bright, v_brightpath, 'LUMINA-NB2: A Phase II, Open-Label, Single-Arm Study of BPC-118 in Combination with Temozolomide in Children and Young People with Relapsed or Refractory High-Risk Neuroblastoma', 'LUMINA-NB2', 'BPC-118-NB2', '1.2', 'interventional', 'phase_2', 'Paediatric Oncology', 'Relapsed or refractory high-risk neuroblastoma', 'paediatric', 1, 17, false, 'open_label', 1, null, 36, '1012446', 'Dr Clara Whitfield', 'setup', '2026-08-01', '2028-01-31', '2030-07-31', true)
  returning id into v_trial;
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_bright, 'Avonside Children''s Hospital Oncology Research Unit', v_uk, 'Upper Maudlin Way', 'Bristol', 'BS2 8QZ', 'Dr Clara Whitfield', 'clara.whitfield@avonside.example', 'Maya Lewis', 'maya.lewis@avonside.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_bright, 'Tyneside Children''s Cancer Centre', v_uk, 'Leazes Crescent', 'Newcastle upon Tyne', 'NE1 4QX', 'Dr Ben Armstrong', 'ben.armstrong@tyneside.example', 'Ruth Collins', 'ruth.collins@tyneside.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
  insert into public.sites (tenant_id, name, country_id, address_line1, city, postal_code, investigator_name, investigator_email, coordinator_name, coordinator_email, status)
  values (v_bright, 'Solent Children''s Hospital Paediatric Oncology Unit', v_uk, 'Tremona Gardens', 'Southampton', 'SO16 6YQ', 'Dr Olivia Bennett', 'olivia.bennett@solent.example', 'Jacob Price', 'jacob.price@solent.example', 'active') returning id into v_site;
  insert into public.trial_sites (trial_id, site_id) values (v_trial, v_site);
end $$;
